B.aoH=new A.F(380,B.a_q)
B.a0s=s(["New \u201cAsk Claude\u201d in the nav: dictate or type a message and chat with Claude, right in Voicley (add your own Anthropic API key once \u2014 stored securely on device). First step of sending messages to Claude from the app."],t.s)
B.amP=new A.F(379,B.a0s)
